mapper.select:
SELECT count(*)
FROM cart c
         JOIN member m ON c.member_id = m.member_id
WHERE c.item_id = #{itemId}
  AND m.id = #{userId}
  AND c.selected_color = #{color}
  AND c.selected_size = #{size}

mapper.update:
UPDATE cart c
    JOIN member m ON c.member_id = m.member_id
    SET c.count = c.count + #{dto.count}
WHERE c.item_id = #{dto.itemId}
  AND m.id = #{userId}
  AND c.selected_color = #{dto.color}
  AND c.selected_size = #{dto.size}

UPDATE cart
SET count = #{count}
WHERE cart_id = #{cartId}
